const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const region = ee.Geometry.Rectangle([85.0, 49.0, 110.0, 55.0], null, false);
    const scale = 1000; // meters
    const maxPixels = 1e9;

    const win1 = {label: 'Oct14±2d', start: '2018-10-12', end: '2018-10-16'};
    const win2 = {label: 'Oct29±2d', start: '2018-10-27', end: '2018-10-31'};

    // 2. Helper functions
    async function getStatsForWindow(win) {
      const datasets = [
        {id: 'MODIS/006/MOD10A1', tag: 'Terra'},
        {id: 'MODIS/006/MYD10A1', tag: 'Aqua'}
      ];

      for (let i = 0; i < datasets.length; i++) {
        const ds = datasets[i];
        let col = ee.ImageCollection(ds.id)
          .filterDate(win.start, win.end)
          .filterBounds(region);

        const size = await col.size().getInfo();
        if (size === 0) {
          continue; // try next dataset
        }

        // Map to fractional snow [0,1] and mask invalid (retain 0..100)
        const processed = col.select('NDSI_Snow_Cover').map(function(img) {
          const snow = img.select('NDSI_Snow_Cover');
          const valid = snow.gte(0).and(snow.lte(100));
          const snowfrac = snow.updateMask(valid).divide(100).toFloat().rename('snowfrac');
          return snowfrac.copyProperties(img, img.propertyNames());
        });

        const mosaicMean = processed.mean();

        // Pixel totals (at analysis scale)
        const totalDict = ee.Image(1).rename('const').reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: region,
          scale: scale,
          maxPixels: maxPixels
        });
        const totalPx = await totalDict.get('const').getInfo();

        const validCountDict = mosaicMean.reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: region,
          scale: scale,
          maxPixels: maxPixels
        });
        const validPx = await validCountDict.get('snowfrac').getInfo();

        if (validPx === null || totalPx === null) {
          return {status: 'C3', detail: 'Null in counts'};
        }

        if (validPx === 0) {
          // Try next dataset if available
          if (i < datasets.length - 1) continue;
          return {status: 'C2', detail: 'No valid pixels'};
        }

        const meanDict = mosaicMean.reduceRegion({
          reducer: ee.Reducer.mean(),
          geometry: region,
          scale: scale,
          maxPixels: maxPixels
        });
        const meanSnow = await meanDict.get('snowfrac').getInfo();

        if (meanSnow === null || Number.isNaN(meanSnow)) {
          return {status: 'C3', detail: 'Mean is null/NaN'};
        }

        const validPct = (validPx / totalPx) * 100.0;

        return {
          status: 'OK',
          dataset: ds.tag,
          datasetId: ds.id,
          images: size,
          totalPx: totalPx,
          validPx: validPx,
          validPct: validPct,
          meanSnow: meanSnow
        };
      }

      // No dataset had images
      return {status: 'C1', detail: 'Empty collection both Terra/Aqua'};
    }

    // 3. Run stats for both windows
    console.log(`Region: Rect[85E,110E,49N,55N], scale=${scale}m`);
    const s1 = await getStatsForWindow(win1);
    const s2 = await getStatsForWindow(win2);

    // 4. Handle failure cases
    function printWindow(wlabel, s) {
      if (s.status === 'OK') {
        const meanPct = (s.meanSnow * 100.0);
        console.log(`${wlabel} ${s.dataset}: images=${s.images}, validPx=${s.validPx}/${s.totalPx} (${s.validPct.toFixed(1)}%), meanSnow=${meanPct.toFixed(2)}%`);
      } else if (s.status === 'C1') {
        console.log(`${wlabel}: 0 images (Empty Collection)`);
      } else if (s.status === 'C2') {
        console.log(`${wlabel}: No valid pixels after masking`);
      } else if (s.status === 'C3') {
        console.log(`${wlabel}: Calculation failure (null/NaN)`);
      }
    }

    printWindow(win1.label, s1);
    printWindow(win2.label, s2);

    // Decide final answer
    // Priority of error codes
    if (s1.status === 'C1' || s2.status === 'C1') {
      console.log('C1');
      return;
    }
    if (s1.status === 'C2' || s2.status === 'C2') {
      console.log('C2');
      return;
    }
    if (s1.status === 'C3' || s2.status === 'C3') {
      console.log('C3');
      return;
    }

    // Both OK
    const delta = (s2.meanSnow - s1.meanSnow) * 100.0; // percentage points
    console.log(`Δ snow (pp): ${delta.toFixed(2)}`);

    // Use 1 percentage point threshold to avoid noise
    if (delta > 1.0) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.error(`Error: ${err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
